import{_ as t,a as r,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Close a Return","description":"","frontmatter":{"outline":false,"examples":[{"id":"close-return","title":"Close a Return","description":"Mark the authenticated customer's own return (RMA) request as solved.","query":"mutation CloseCustomerReturn($id: ID!) {\\n  closeCustomerReturn(input: { id: $id }) {\\n    customerReturn {\\n      _id\\n      orderId\\n      orderIncrementId\\n      statusId\\n      statusTitle\\n      statusColor\\n      canClose\\n      canReopen\\n      isExpired\\n      messagesCount\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/shop/returns/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"closeCustomerReturn\\": {\\n      \\"customerReturn\\": {\\n        \\"_id\\": 12,\\n        \\"orderId\\": 45,\\n        \\"orderIncrementId\\": \\"000000045\\",\\n        \\"statusId\\": 3,\\n        \\"statusTitle\\": \\"Solved\\",\\n        \\"statusColor\\": \\"#12B76A\\",\\n        \\"canClose\\": false,\\n        \\"canReopen\\": false,\\n        \\"isExpired\\": false,\\n        \\"messagesCount\\": 3,\\n        \\"updatedAt\\": \\"2026-07-20T11:10:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"close not allowed","cause":"The return is not in a state that can be closed","solution":"Only a return whose canClose flag is true can be closed"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The return does not exist or is not owned by the authenticated customer","solution":"Only return IDs belonging to the logged-in customer can be closed"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/mutations/close-return.md","filePath":"api/graphql-api/shop/returns/mutations/close-return.md","lastUpdated":1787290888000}`),a={name:"api/graphql-api/shop/returns/mutations/close-return.md"};function n(s,e,u,c,i,l){return o(),r("div",null,e[0]||(e[0]=[d('<h1 id="close-a-return" tabindex="-1">Close a Return <a class="header-anchor" href="#close-a-return" aria-label="Permalink to &quot;Close a Return&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>closeCustomerReturn</code> mutation marks the customer&#39;s own return (RMA) request as <code>Solved</code> and adds a note to the conversation thread. The result carries the updated return. A return can only be closed when its <code>canClose</code> flag is <code>true</code>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>The return IRI, e.g. <code>/api/shop/returns/12</code>.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>customerReturn._id</code></td><td><code>Int!</code></td><td>Numeric return ID.</td></tr><tr><td><code>customerReturn.orderId</code></td><td><code>Int!</code></td><td>Id of the order the item belongs to.</td></tr><tr><td><code>customerReturn.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>customerReturn.statusId</code></td><td><code>Int!</code></td><td>Numeric status id after closing — <code>3</code> (Solved).</td></tr><tr><td><code>customerReturn.statusTitle</code></td><td><code>String!</code></td><td>Status label, e.g. <code>Solved</code>.</td></tr><tr><td><code>customerReturn.statusColor</code></td><td><code>String!</code></td><td>Hex color for the status badge.</td></tr><tr><td><code>customerReturn.canClose</code></td><td><code>Boolean</code></td><td>Whether the return can be closed.</td></tr><tr><td><code>customerReturn.canReopen</code></td><td><code>Boolean</code></td><td>Whether the return can be reopened.</td></tr><tr><td><code>customerReturn.isExpired</code></td><td><code>Boolean</code></td><td>Whether the return is past its action window.</td></tr><tr><td><code>customerReturn.messagesCount</code></td><td><code>Int!</code></td><td>Number of conversation messages — incremented by the close note.</td></tr><tr><td><code>customerReturn.updatedAt</code></td><td><code>DateTime!</code></td><td>Return last update timestamp.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/mutations/reopen-return.html">Reopen a Return</a></li><li><a href="/api/graphql-api/shop/returns/queries/view-return.html">View Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',11)]))}const m=t(a,[["render",n]]);export{p as __pageData,m as default};
